                        raised = True
                        raised_exc = exc
                    if not raised:
                        ok = bool(
                            evaluate_expression(
                                test["mutation"]["assertion"], None, tolerance_policy(test, default_tol), env
                            )
                        )
                else:
                    raised = False
                    raised_exc = None
                    try:
                        actual = callable_under_test(*[decode_arg(arg) for arg in test["args"]])
                    except Exception as exc:
                        raised = True
                        raised_exc = exc
                        actual = None
                if test["kind"] == "loop":
                    pass
                elif test["kind"] == "mutation":
